SET TRANSACTION READ ONLY;SET LOCAL statement_timeout='100s';SET LOCAL ROLE needacabplus_shared_reader;
DO $$ DECLARE result jsonb;BEGIN
WITH b AS MATERIALIZED(SELECT "externalId",status,"bookingSource" source,"driverId","driverCallSign","dispatchedAt","arrivedAt","pickedUpAt","completedAt","bookedAtTime",price,
 date_trunc('month',"pickupDueTime") pickup_month,
 greatest(COALESCE(distance,0),COALESCE("systemDistance",0),COALESCE("meterDistance",0),COALESCE("meterDistanceMetres",0),COALESCE("gpsMeterDistance",0),COALESCE("estimatedDistance",0))>0 positive
 FROM "Booking"),
s AS MATERIALIZED(SELECT source,status,pickup_month,positive,count(*) n,count(*)FILTER(WHERE "pickedUpAt" IS NOT NULL) pob,count(*)FILTER(WHERE "dispatchedAt" IS NOT NULL) dispatched,count(*)FILTER(WHERE nullif(btrim("driverCallSign"),'') IS NOT NULL AND "driverCallSign"<>'0') driver,count(*)FILTER(WHERE price>0) paid FROM b GROUP BY 1,2,3,4),
matched AS MATERIALIZED(SELECT n.source,n.status,n.n no_positive_jobs,n.pob no_positive_pob,n.dispatched no_positive_dispatched,n.driver no_positive_driver,n.paid no_positive_paid,p.n positive_controls,p.pob positive_pob,p.dispatched positive_dispatched,p.driver positive_driver,p.paid positive_paid FROM s n JOIN s p ON n.source IS NOT DISTINCT FROM p.source AND n.status=p.status AND n.pickup_month=p.pickup_month AND p.positive WHERE NOT n.positive)
SELECT jsonb_build_object(
 'sentinel_driver_ids',(SELECT jsonb_agg(x) FROM(SELECT positive,count(*)FILTER(WHERE "driverId"='0') driver_id_zero,count(*)FILTER(WHERE btrim("driverCallSign")='0') callsign_zero,count(*)FILTER(WHERE nullif(btrim("driverCallSign"),'') IS NOT NULL AND btrim("driverCallSign")<>'0') callsign_nonzero FROM b GROUP BY positive)x),
 'completed_by_source',(SELECT jsonb_agg(x) FROM(SELECT source,positive,count(*) jobs,count(*)FILTER(WHERE "dispatchedAt"="pickedUpAt") dispatch_equals_pob,count(*)FILTER(WHERE "pickedUpAt"="completedAt") pob_equals_completion,count(*)FILTER(WHERE "dispatchedAt"="pickedUpAt" AND "pickedUpAt"="completedAt") all_three_equal,count(*)FILTER(WHERE "completedAt">"pickedUpAt") positive_trip_duration,count(*)FILTER(WHERE "completedAt"<"pickedUpAt") negative_trip_duration,count(*)FILTER(WHERE "arrivedAt" IS NOT NULL) arrived,count(*)FILTER(WHERE price=0) price_zero,percentile_cont(0.5)WITHIN GROUP(ORDER BY extract(epoch from("completedAt"-"pickedUpAt"))/60) FILTER(WHERE "completedAt">="pickedUpAt") median_trip_minutes FROM b WHERE status='COMPLETED' AND source IN('FlaggedBooking','OperatorWeb','MobileApp') GROUP BY 1,2 ORDER BY 1,2)x),
 'matched_comparison',(SELECT jsonb_build_object('no_positive_covered',sum(no_positive_jobs),'positive_controls',sum(positive_controls),'no_positive_pob_rate',sum(no_positive_pob)::numeric/nullif(sum(no_positive_jobs),0),'weighted_control_pob_rate',sum(no_positive_jobs::numeric*positive_pob/positive_controls)/nullif(sum(no_positive_jobs),0),'no_positive_dispatch_rate',sum(no_positive_dispatched)::numeric/nullif(sum(no_positive_jobs),0),'weighted_control_dispatch_rate',sum(no_positive_jobs::numeric*positive_dispatched/positive_controls)/nullif(sum(no_positive_jobs),0),'no_positive_positive_price_rate',sum(no_positive_paid)::numeric/nullif(sum(no_positive_jobs),0),'weighted_control_positive_price_rate',sum(no_positive_jobs::numeric*positive_paid/positive_controls)/nullif(sum(no_positive_jobs),0)) FROM matched),
 'completed_nonpositive_timing',(SELECT jsonb_build_object('jobs',count(*),'has_dispatch_and_pob',count(*)FILTER(WHERE "dispatchedAt" IS NOT NULL AND "pickedUpAt" IS NOT NULL),'pob_before_dispatch',count(*)FILTER(WHERE "pickedUpAt"<"dispatchedAt"),'completion_before_pob',count(*)FILTER(WHERE "completedAt"<"pickedUpAt"),'all_three_equal',count(*)FILTER(WHERE "dispatchedAt"="pickedUpAt" AND "pickedUpAt"="completedAt")) FROM b WHERE NOT positive AND status='COMPLETED')
) INTO result;RAISE NOTICE 'ZERO_DISTANCE_COMPARISONS %',result;END $$;
